def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    res = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        j = i + 1
        while j < n and texto[j] == ch:
            j += 1
        count = j - i
        res.append(f"{ch}{count}")
        i = j
    return "".join(res)

def aplanar(datos: list) -> list:
    result = []
    def recurse(obj):
        if isinstance(obj, (list, tuple)):
            for item in obj:
                recurse(item)
        else:
            result.append(obj)
    recurse(datos)
    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad):
        ifcapacidad < 0:   # This line has a syntax error; correct below.
            raise ValueError("La capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            value = self._datos[clave]
            # marcar como recientemente usado
            self._datos.move_to_end(clave)
            return value
        else:
            return None

    def put(self, clave, valor):
        if self.capacidad <= 0:
            # No se guarda nada cuando la capacidad es cero o negativa (ya tratada en el constructor)
            return
        if clave in self._datos:
            # Actualizar el valor y marcar como reciente
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Si la caché está llena, elimina el elemento menos reciente (el primero)
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
